def transform(grid):
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            a, b = grid[:r], grid[r + 1:]
            return [[2 if x and y else 0 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            return [[2 if row[k] and row[c + 1 + k] else 0 for k in range(c)] for row in grid]
    raise ValueError("separator not found")

